113:             }
114:             try {
115:                 companionContext.recallCognition(request.userId(), request.query()).ifPresent(candidates::add);
116:             } catch (RuntimeException exception) {
117:                 log.warn("陪伴认知上下文读取降级：errorType={}", exception.getClass().getSimpleName());
118:             }
119:             candidates.addAll(result.fragments());
120:             for (var fragment : candidates) {
121:                 if (accepted >= request.memoryTopK() || remaining <= 0) break;
122:                 if (fragment.content() == null || PersonalContextSafety.containsSensitive(fragment.content())
123:                         || !seen.add(fragment.content().strip().replaceAll("\\s+", " "))) continue;
