440:     private boolean pauseForConfirmation(AgentRun run, List<ToolUseBlock> askedTools, AgentStreamSession streamSession) {
441:         List<ConfirmResult> rememberResults = new ArrayList<>();
442:         List<ToolUseBlock> unresolved = new ArrayList<>();
443: 
444:         for (ToolUseBlock tool : askedTools) {
445:             Optional<Boolean> remembered = pendingApprovalStore.remembered(
446:                     run.userId(),
447:                     run.sessionId(),
448:                     tool
449:             );
450:             if (remembered.isPresent()) {
451:                 // 已记住也要走 ConfirmResult，不能跳过 AgentScope 的状态恢复流程
452:                 rememberResults.add(new ConfirmResult(remembered.get(), tool));
453:             } else {
454:                 unresolved.add(tool);
455:             }
456:         }
457: 
458:         if (unresolved.isEmpty()) {
459:             Msg resumeMessage = buildResumeMessage(rememberResults);
460:             runAgentStream(run, List.of(resumeMessage), streamSession);
461:             return true;
462:         }
463: 
464:         // 已记住的结果也放入统一 PendingApproval，确保最终一次恢复包含整批工具的结果
465:         PendingApproval approval = new PendingApproval(run, askedTools, streamSession.runId());
466:         rememberResults.forEach(result -> approval.decide(
467:                 result.getToolCall().getId(), result.isConfirmed()
468:         ));
469:         pendingApprovalStore.save(approval);
470:         checkpointService.save(run);
471: 
472:         return putEvent(
473:                 streamSession,
474:                 new AgentStreamEvent.PermissionRequired(
475:                         approval.approvalId(), approval.runId(), run.turnId(), approval.pendingTools())
476:         );
477:     }
