83:     /**
84:      * 解析 YAML 文件并转换为 AgentScope 原生 PermissionRule。
85:      *
86:      * @param yamlPath YAML 文件绝对路径
87:      * @return 解析出的 PermissionRule 列表
88:      */
89:     @SuppressWarnings("unchecked")
90:     private List<PermissionRule> parseYamlRules(Path yamlPath) {
91:         List<PermissionRule> rules = new ArrayList<>();
92:         try (InputStream in = Files.newInputStream(yamlPath)) {
93:             Yaml yaml = new Yaml();
94:             Map<String, Object> data = yaml.load(in);
95: 
96:             if (data != null && data.containsKey("rules")) {
97:                 List<Map<String, Object>> ruleList = (List<Map<String, Object>>) data.get("rules");
98:                 for (Map<String, Object> map : ruleList) {
99:                     String toolName = (String) map.getOrDefault("tool", "*");
100:                     String pattern = (String) map.getOrDefault("pattern", ".*");
101:                     String action = (String) map.getOrDefault("action", "ALLOW");
102: 
103:                     PermissionBehavior behavior = switch (action.toUpperCase()) {
104:                         case "DENY" -> PermissionBehavior.DENY;
105:                         case "ASK" -> PermissionBehavior.ASK;
106:                         default -> PermissionBehavior.ALLOW;
107:                     };
108: 
109:                     // 直接构造 AgentScope 原生 PermissionRule
110:                     rules.add(new PermissionRule(toolName, pattern, behavior, "Layer2-YamlUserRule"));
111:                 }
112:             }
113:         } catch (Exception e) {
114:             log.error("[PermissionChecker] 解析 YAML 权限文件失败: {}", yamlPath, e);
115:         }
116:         return rules;
117:     }
118: }

