441:     /** 优先应用已经记住的决定，未解决的工具进入待确认批次。 */
442:     private boolean pauseForConfirmation(AgentRun run, List<ToolUseBlock> askedTools, AgentStreamSession streamSession) {
443:         List<ConfirmResult> rememberResults = new ArrayList<>();
444:         List<ToolUseBlock> unresolved = new ArrayList<>();
445: 
446:         for (ToolUseBlock tool : askedTools) {
447:             Optional<Boolean> remembered = pendingApprovalStore.remembered(
448:                     run.userId(),
449:                     run.sessionId(),
450:                     tool
451:             );
452:             if (remembered.isPresent()) {
453:                 // 已记住也要走 ConfirmResult，不能跳过 AgentScope 的状态恢复流程
454:                 rememberResults.add(new ConfirmResult(remembered.get(), tool));
455:             } else {
456:                 unresolved.add(tool);
457:             }
458:         }
459: 
460:         if (unresolved.isEmpty()) {
461:             Msg resumeMessage = buildResumeMessage(rememberResults);
462:             runAgentStream(run, List.of(resumeMessage), streamSession);
463:             return true;
464:         }
465: 
466:         // 已记住的结果也放入统一 PendingApproval，确保最终一次恢复包含整批工具的结果
467:         PendingApproval approval = new PendingApproval(run, askedTools, streamSession.runId());
468:         rememberResults.forEach(result -> approval.decide(
469:                 result.getToolCall().getId(), result.isConfirmed()
470:         ));
471:         pendingApprovalStore.save(approval);
472:         checkpointService.save(run);
473: 
474:         return putEvent(
475:                 streamSession,
476:                 new AgentStreamEvent.PermissionRequired(
477:                         approval.approvalId(), approval.runId(), run.turnId(), approval.pendingTools())
478:         );
479:     }
