package butvan.agent.agents.agent;

import butvan.agent.agents.agent.event.AgentStreamEvent;
import butvan.agent.agents.agent.permission.PendingApprovalStore;
import butvan.agent.agents.agent.run.AgentRun;
import butvan.agent.agents.agent.run.AgentRunCheckpointService;
import butvan.agent.agents.agent.run.AgentRunCompleter;
import butvan.agent.agents.context.ProfileMaintenanceScheduler;
import butvan.agent.agents.model.ModelHolder;
import butvan.agent.agents.model.ModelSelector;
import butvan.agent.agents.session.AgentStreamSession;
import butvan.agent.agents.session.SessionCatalogService;
import butvan.agent.agents.session.dto.SessionPermissionMode;
import butvan.agent.agents.session.dto.TranscriptMessageDto;
import butvan.agent.agents.usage.ModelIdentity;
import io.agentscope.core.event.AgentEvent;
import io.agentscope.core.event.ModelCallEndEvent;
import io.agentscope.core.event.RequireUserConfirmEvent;
import io.agentscope.core.message.Msg;
import io.agentscope.core.message.ToolUseBlock;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.util.List;

/**
 * 流式事件消费与终态收尾执行器。
 *
 * <p>负责订阅 {@link AgentRuntimeAdapter} 产出的事件流，采集模型 Token 用量、
 * 持久化检查点、向 SSE 队列转发事件，并在取消、失败或自然结束时确保只写入一次终态。</p>
 */
@Slf4j
@RequiredArgsConstructor
class AgentStreamExecutor {

    @FunctionalInterface
    interface ConfirmationPauseHandler {
        boolean pause(AgentRun run, List<ToolUseBlock> askedTools, AgentStreamSession streamSession);
    }

    private final ModelHolder modelHolder;
    private final SessionCatalogService sessionCatalogService;
    private final PendingApprovalStore pendingApprovalStore;
    private final AgentEventManager agentEventManager;
    private final AgentRunCompleter agentRunCompleter;
    private final AgentRunCheckpointService checkpointService;
    private final ProfileMaintenanceScheduler profileMaintenanceScheduler;
    private final AgentRuntimeAdapter runtimeAdapter;

    /** 消费单次或恢复后的 AgentScope 事件流，直到终态或等待人工审批暂停。 */
    void execute(
            AgentRun run,
            List<Msg> inputMessages,
            AgentStreamSession streamSession,
            ConfirmationPauseHandler confirmationPauseHandler
    ) {
        ModelIdentity modelIdentity = currentModelIdentity();
        SessionPermissionMode productMode = sessionCatalogService.getPermissionMode(run.sessionId());

        for (AgentEvent event : runtimeAdapter.streamEvents(run, productMode, inputMessages, streamSession)) {
            // Token usage 必须在 UI 映射之前采集，包含工具循环和子 Agent 原始事件。
            run.recordModelEvent(event, modelIdentity);

            if (streamSession.isCancelled()) {
                finishCancelled(run, streamSession);
                return;
            }

            // 必须在普通映射之前识别权限确认事件
            if (event instanceof RequireUserConfirmEvent confirmEvent) {
                if (confirmationPauseHandler.pause(run, confirmEvent.getToolCalls(), streamSession)) {
                    return;
                }
                continue;
            }

            AgentStreamEvent mapped = agentEventManager.map(
                    event, run.toolArgsBuffer(), run.toolResultPrefixBuffer());
            run.record(mapped);
            if (event instanceof ModelCallEndEvent) {
                checkpointService.save(run);
            }
            if (mapped != null && mapped.isTerminal()) {
                completeWithTerminalEvent(run, streamSession, mapped);
                return;
            }
            if (mapped != null && !putEvent(streamSession, mapped)) {
                finishCancelled(run, streamSession);
                return;
            }
        }

        if (streamSession.isCancelled()) {
            finishCancelled(run, streamSession);
            return;
        }
        completeWithTerminalEvent(run, streamSession, new AgentStreamEvent.Completed());
    }

    /** 先持久化 partial assistant，再将取消终态交给 SSE。 */
    void finishCancelled(AgentRun run, AgentStreamSession streamSession) {
        // Thread.interrupt 会让 Files.lines 直接抛出 ClosedByInterruptException；
        // 取消只应终止模型/工具，不应打断最后一次 transcript 收尾。
        boolean interrupted = Thread.interrupted();
        try {
            if (agentRunCompleter.tryComplete(run, TranscriptMessageDto.MessageStatus.CANCELLED)) {
                streamSession.offerTerminal(new AgentStreamEvent.Cancelled(streamSession.runId()));
            } else {
                streamSession.offerTerminal(
                        new AgentStreamEvent.Failed(terminalPersistenceFailureMessage(true)));
            }
        } finally {
            if (interrupted) Thread.currentThread().interrupt();
        }
    }

    /** 统一处理流执行异常：区分客户端取消与业务/权限失败并落盘终态。 */
    void handleStreamFailure(
            AgentRun run,
            String sessionId,
            AgentStreamSession streamSession,
            Exception exception,
            String fallbackFailureMessage
    ) {
        if (streamSession.isCancelled() || Thread.currentThread().isInterrupted()) {
            Thread.currentThread().interrupt();
            if (run != null) {
                finishCancelled(run, streamSession);
            } else {
                streamSession.offerTerminal(new AgentStreamEvent.Cancelled(streamSession.runId()));
            }
            return;
        }

        log.error("Agent 流处理失败：sessionId={}", sessionId, exception);
        String userMessage = exception instanceof IllegalArgumentException
                ? exception.getMessage()
                : fallbackFailureMessage;
        if (run != null && isWaitingForPermission(run, exception)) {
            userMessage = "该会话仍有操作等待桌面端权限确认，请现在 ButvanAgent 桌面端处理后再继续";
        }
        if (run != null && !agentRunCompleter.tryComplete(run, TranscriptMessageDto.MessageStatus.FAILED)) {
            userMessage = terminalPersistenceFailureMessage(false);
        }
        putEvent(streamSession, new AgentStreamEvent.Failed(userMessage));
    }

    boolean putEvent(AgentStreamSession streamSession, AgentStreamEvent event) {
        if (event.isTerminal()) return streamSession.offerTerminal(event);
        try {
            streamSession.queue().put(event);
            return true;
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    String terminalPersistenceFailureMessage(boolean stopped) {
        return stopped
                ? "Agent 已停止，但聊天记录保存失败。请检查磁盘空间与数据目录权限后重试。"
                : "Agent 已结束，但聊天记录保存失败。请检查磁盘空间与数据目录权限后重试。";
    }

    private void completeWithTerminalEvent(
            AgentRun run,
            AgentStreamSession streamSession,
            AgentStreamEvent terminalEvent
    ) {
        // 先持久化再发送终态，确保前端收到 done 后能立即读取完整消息与 usage。
        if (agentRunCompleter.tryComplete(run, TranscriptMessageDto.MessageStatus.COMPLETED)) {
            profileMaintenanceScheduler.consider(run.userId());
            putEvent(streamSession, terminalEvent);
        } else {
            putEvent(streamSession, new AgentStreamEvent.Failed(terminalPersistenceFailureMessage(false)));
        }
    }

    private ModelIdentity currentModelIdentity() {
        ModelSelector selector = modelHolder.getCurrentSelector();
        String vendor = selector == null ? null : selector.vendor();
        return new ModelIdentity(vendor, modelHolder.getModel().getModelName());
    }

    /**
     * 判断失败是否由“待确认的权限审批”引起。
     *
     * <p>优先查待确认存储；再兼容框架 paused for human-in-the-loop 异常信息，
     * 避免会话残留 ASKING 状态时向用户暴露框架异常。</p>
     */
    private boolean isWaitingForPermission(AgentRun run, Exception e) {
        if (pendingApprovalStore.hasPending(run.userId(), run.sessionId())) {
            return true;
        }
        return e instanceof IllegalStateException
                && e.getMessage() != null
                && e.getMessage().contains("paused for human-in-the-loop");
    }
}

package butvan.agent.agents.agent;

import butvan.agent.agents.agent.event.AgentStreamEvent;
import butvan.agent.agents.agent.permission.PendingApproval;
import butvan.agent.agents.agent.permission.PendingApprovalStore;
import butvan.agent.agents.agent.permission.PendingApprovalView;
import butvan.agent.agents.agent.permission.PermissionBatchDecisionRequest;
import butvan.agent.agents.agent.permission.PermissionDecisionRequest;
import butvan.agent.agents.agent.permission.PermissionDecisionResponse;
import butvan.agent.agents.agent.permission.PermissionToolDecision;
import butvan.agent.agents.agent.permission.PermissionToolDto;
import butvan.agent.agents.agent.run.ActiveAgentRunRegistry;
import butvan.agent.agents.agent.run.AgentRun;
import butvan.agent.agents.agent.run.AgentRunCheckpointService;
import butvan.agent.agents.agent.run.AgentRunCompleter;
import butvan.agent.agents.material.ReplyImages;
import butvan.agent.agents.model.ModelHolder;
import butvan.agent.agents.session.AgentStreamSession;
import butvan.agent.agents.session.AgentTurnResult;
import butvan.agent.agents.session.SessionCatalogService;
import butvan.agent.agents.session.dto.TranscriptMessageDto;
import io.agentscope.core.event.ConfirmResult;
import io.agentscope.core.message.Msg;
import io.agentscope.core.message.ToolUseBlock;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * 人工介入（HITL）权限审批与恢复协调器。
 *
 * <p>集中管理待确认工具批次的暂停、会话级记忆匹配、前端审批决定保存、
 * 取消待审轮次以及审批通过后的流恢复。</p>
 */
@Slf4j
@RequiredArgsConstructor
class AgentApprovalCoordinator {

    private final ModelHolder modelHolder;
    private final SessionCatalogService sessionCatalogService;
    private final PendingApprovalStore pendingApprovalStore;
    private final AgentRunCompleter agentRunCompleter;
    private final AgentRunCheckpointService checkpointService;
    private final ActiveAgentRunRegistry activeRunRegistry;
    private final AgentRuntimeAdapter runtimeAdapter;
    private final AgentStreamExecutor streamExecutor;

    /** 优先应用已经记住的决定，未解决的工具进入待确认批次。 */
    boolean pauseForConfirmation(AgentRun run, List<ToolUseBlock> askedTools, AgentStreamSession streamSession) {
        List<ConfirmResult> rememberResults = new ArrayList<>();
        List<ToolUseBlock> unresolved = new ArrayList<>();

        for (ToolUseBlock tool : askedTools) {
            Optional<Boolean> remembered = pendingApprovalStore.remembered(
                    run.userId(), run.sessionId(), tool);
            if (remembered.isPresent()) {
                // 已记住也要走 ConfirmResult，不能跳过 AgentScope 的状态恢复流程
                rememberResults.add(new ConfirmResult(remembered.get(), tool));
            } else {
                unresolved.add(tool);
            }
        }

        if (unresolved.isEmpty()) {
            Msg resumeMessage = runtimeAdapter.buildResumeMessage(rememberResults);
            streamExecutor.execute(run, List.of(resumeMessage), streamSession, this::pauseForConfirmation);
            return true;
        }

        // 已记住的结果也放入统一 PendingApproval，确保最终一次恢复包含整批工具的结果
        PendingApproval approval = new PendingApproval(run, askedTools, streamSession.runId());
        rememberResults.forEach(result -> approval.decide(
                result.getToolCall().getId(), result.isConfirmed()));
        pendingApprovalStore.save(approval);
        checkpointService.save(run);

        return streamExecutor.putEvent(
                streamSession,
                new AgentStreamEvent.PermissionRequired(
                        approval.approvalId(), approval.runId(), run.turnId(), approval.pendingTools())
        );
    }

    /** 原子保存当前批次的全部审核决定，完成后由前端恢复原运行。 */
    PermissionDecisionResponse decidePermissions(String userId, PermissionBatchDecisionRequest request) {
        sessionCatalogService.requireActive(request.sessionId());
        PendingApproval approval = pendingApprovalStore.require(
                request.approvalId(), userId, request.sessionId());
        approval.decideBatch(request.decisions());

        for (PermissionToolDecision decision : request.decisions()) {
            if (decision.rememberForSession()) {
                ToolUseBlock tool = approval.findTool(decision.toolCallId());
                pendingApprovalStore.remember(
                        userId, request.sessionId(), tool, decision.approved());
            }
        }
        return PermissionDecisionResponse.ready();
    }

    PermissionDecisionResponse decidePermission(String userId, PermissionDecisionRequest request) {
        sessionCatalogService.requireActive(request.sessionId());
        PendingApproval approval = pendingApprovalStore.require(
                request.approvalId(), userId, request.sessionId());

        approval.decide(request.toolCallId(), request.approved());

        if (request.rememberForSession()) {
            ToolUseBlock tool = approval.findTool(request.toolCallId());
            // 记住的仅是这一组完全相同的参数；不写 YAML，不影响其他会话。
            pendingApprovalStore.remember(userId, request.sessionId(), tool, request.approved());
        }

        PermissionToolDto next = approval.nextTool();
        return next == null ? PermissionDecisionResponse.ready()
                : PermissionDecisionResponse.next(next);
    }

    /** 自动批准当前批次的全部待确认工具并恢复流式执行。 */
    AgentStreamSession autoApproveAndResume(String userId, String sessionId, String approvalId) {
        PendingApproval approval = pendingApprovalStore.require(approvalId, userId, sessionId);
        approval.approveAll();
        log.info("自动批准工具权限：sessionId={}, approvalId={}, 工具数={}",
                sessionId, approvalId, approval.toolCount());
        return resumeAgent(userId, sessionId, approvalId, approval.runId());
    }

    /** 取消已暂停的精确轮次，不恢复模型或执行任何已请求工具。 */
    AgentTurnResult cancelPendingApproval(String userId, String sessionId, String approvalId, String runId) {
        sessionCatalogService.requireActive(sessionId);
        PendingApproval approval = pendingApprovalStore.claimForCancellation(approvalId, userId, sessionId, runId);
        if (!agentRunCompleter.tryComplete(approval.run(), TranscriptMessageDto.MessageStatus.CANCELLED)) {
            pendingApprovalStore.restoreAfterFailedResume(approval);
            throw new IllegalStateException("取消后的聊天记录保存失败");
        }
        return approval.run().persistedResult(runId);
    }

    /** 使用原 runId 恢复权限确认后的同一轮运行。 */
    AgentStreamSession resumeAgent(String userId, String sessionId, String approvalId, String runId) {
        PendingApproval approval = pendingApprovalStore.claimForResume(
                approvalId, userId, sessionId, runId);
        AgentStreamSession streamSession = new AgentStreamSession(runId);
        streamSession.queue().offer(new AgentStreamEvent.RunStarted(runId));
        Thread producer = Thread.ofVirtual().unstarted(() -> {
            try {
                if (!modelHolder.isInitialized()) {
                    agentRunCompleter.tryComplete(approval.run(), TranscriptMessageDto.MessageStatus.FAILED);
                    streamExecutor.putEvent(streamSession, new AgentStreamEvent.Failed("请先完成模型配置"));
                    return;
                }
                List<ConfirmResult> results = approval.toConfirmResults();
                ReplyImages images = approval.run().runtimeContext().get(ReplyImages.class);
                if (images != null && results.stream().anyMatch(result -> result.isConfirmed()
                        && ReplyImages.SCREEN_TOOL.equals(result.getToolCall().getName()))) {
                    images.approveScreenshot();
                }
                streamExecutor.execute(
                        approval.run(),
                        List.of(runtimeAdapter.buildResumeMessage(results)),
                        streamSession,
                        this::pauseForConfirmation
                );
            } catch (Exception exception) {
                streamExecutor.handleStreamFailure(
                        approval.run(), sessionId, streamSession, exception, "恢复 Agent 处理失败，请重新发起任务。");
            } finally {
                activeRunRegistry.unregister(userId, sessionId, streamSession);
                streamSession.settle(approval.run().persistedResult(streamSession.runId()));
            }
        });
        try {
            activeRunRegistry.register(userId, sessionId, streamSession);
            streamSession.bindProducer(producer);
            producer.start();
        } catch (RuntimeException exception) {
            activeRunRegistry.unregister(userId, sessionId, streamSession);
            pendingApprovalStore.restoreAfterFailedResume(approval);
            throw exception;
        }
        return streamSession;
    }

    /** 查询当前用户在指定会话中等待处理的审批。 */
    Optional<PendingApprovalView> currentPendingApproval(String userId, String sessionId) {
        sessionCatalogService.requireActive(sessionId);
        return pendingApprovalStore.current(userId, sessionId);
    }
}

package butvan.agent.agents.agent;

import butvan.agent.agents.agent.event.AgentStreamEvent;
import butvan.agent.agents.agent.run.AgentRun;
import butvan.agent.agents.agent.run.AgentRunCheckpointService;
import butvan.agent.agents.context.ContextEnvelope;
import butvan.agent.agents.context.ContextRequest;
import butvan.agent.agents.context.ConversationContextAssembler;
import butvan.agent.agents.material.ChatMaterialRecorder;
import butvan.agent.agents.material.ReplyImages;
import butvan.agent.agents.memory.MemorySourcePolicy;
import butvan.agent.agents.memory.MemorySourceRegistry;
import butvan.agent.agents.memory.MemoryTurnLifecycle;
import butvan.agent.agents.model.ModelHolder;
import butvan.agent.agents.review.UserTurnActivityListener;
import butvan.agent.agents.routing.ToolCapabilityRouter;
import butvan.agent.agents.routing.ToolRoutingDecision;
import butvan.agent.agents.routing.ToolRoutingRequest;
import butvan.agent.agents.session.AgentStreamSession;
import butvan.agent.agents.session.SessionCatalogService;
import butvan.agent.agents.session.TranscriptService;
import butvan.agent.agents.session.dto.SessionChannel;
import butvan.agent.agents.session.dto.SessionKind;
import butvan.agent.agents.tool.ToolCapabilityCatalog;
import io.agentscope.core.agent.RuntimeContext;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.function.Supplier;
import java.util.stream.Collectors;

/**
 * 单轮对话启动前的准备器。
 *
 * <p>负责输入校验、渠道隔离校验、用户消息与图片落盘、检查点保存，
 * 并通过虚拟线程并行执行上下文组装与 Jev 工具路由，减少主模型首字响应前的串行等待。</p>
 */
@Slf4j
@RequiredArgsConstructor
class AgentTurnPreparation {

    record PreparedTurn(AgentRun run, String input, boolean cancelled) {
        static PreparedTurn cancelled(AgentRun run) {
            return new PreparedTurn(run, null, true);
        }

        static PreparedTurn ready(AgentRun run, String input) {
            return new PreparedTurn(run, input, false);
        }
    }

    private final ModelHolder modelHolder;
    private final SessionCatalogService sessionCatalogService;
    private final TranscriptService transcriptService;
    private final AgentRunCheckpointService checkpointService;
    private final ConversationContextAssembler contextAssembler;
    private final ToolCapabilityRouter toolCapabilityRouter;
    private final ToolCapabilityCatalog toolCapabilityCatalog;
    private final AgentRuntimeAdapter runtimeAdapter;
    private final AgentStreamExecutor streamExecutor;
    private final Supplier<MemoryTurnLifecycle> memoryLifecycleSupplier;
    private final Supplier<UserTurnActivityListener> activityListenerSupplier;
    private final Supplier<ChatMaterialRecorder> materialRecorderSupplier;

    /** 在创建后台虚拟线程之前执行的同步入口校验。 */
    void validateIncomingCall(AgentUserCall request) {
        if (request == null) throw new IllegalArgumentException("聊天请求不能为空");
        if (!request.images().isEmpty() && !modelHolder.supportsVision()) {
            throw new IllegalArgumentException("当前模型未标注图片识别能力，请在模型配置中开启或切换到视觉模型");
        }
        if (request.images().size() > AgentImages.MAX_COUNT
                || request.images().stream().mapToLong(AgentImageAttachment::sizeBytes).sum() > AgentImages.MAX_TOTAL_BYTES) {
            throw new IllegalArgumentException("每轮最多 4 张图片，总大小不能超过 12 MiB");
        }
    }

    /** 准备单轮运行上下文；若提前收到取消信号则返回 {@code cancelled = true}。 */
    PreparedTurn prepare(
            AgentUserCall request,
            String userId,
            AgentStreamSession streamSession,
            java.util.function.Consumer<AgentRun> runConsumer
    ) {
        if (request == null) throw new IllegalArgumentException("聊天请求不能为空");

        var currentSession = sessionCatalogService.requireActive(request.sessionId());
        boolean feishuSession = sessionCatalogService.getChannel(request.sessionId()) == SessionChannel.FEISHU;
        boolean feishuCall = request.memoryChannel() == MemorySourceRegistry.Channel.FEISHU;
        if (feishuSession != feishuCall) {
            throw new IllegalArgumentException("会话渠道不匹配，请在原渠道继续对话");
        }

        String requestedContext = request.context() == null || request.context().isBlank()
                ? request.content() : request.context();
        String input = requireContent(requestedContext);
        String displayContent = request.content() == null || request.content().isBlank()
                ? input : request.content().strip();

        String resolvedTurnId = resolveTurnId(request);
        List<String> imageFileIds = persistUserImages(request, userId, currentSession, resolvedTurnId);
        String turnId = transcriptService.appendUserMessageWithTurnId(
                request.sessionId(), displayContent, resolvedTurnId, imageFileIds);
        notifyUserTurnHooks(request, userId, turnId);

        RuntimeContext context = runtimeAdapter.createRuntimeContext(userId, request.sessionId());
        configureReplyImages(context, request.sessionId(), userId, turnId, currentSession, feishuSession);
        AgentRun run = new AgentRun(request.sessionId(), userId, turnId, context);
        runConsumer.accept(run);
        checkpointService.save(run);

        boolean remoteEligible = currentSession != null
                && currentSession.kind() == SessionKind.GENERAL
                && (currentSession.projectId() == null || currentSession.projectId().isBlank())
                && MemorySourcePolicy.eligible(request);
        Set<String> availableGroups = availableToolGroups(feishuSession);

        ParallelPrepResult prepResult = runParallelPreparation(
                userId, displayContent,
                remoteEligible ? request.memoryChannel() : null,
                availableGroups, streamSession
        );
        context.put(ContextEnvelope.class, prepResult.contextEnvelope());

        // 仅新用户轮次修复进程重启遗留调用；HITL 恢复必须让 AgentScope 原样消费 ConfirmResult。
        runtimeAdapter.recoverOrphanedToolCalls(userId, request.sessionId());
        if (streamSession.isCancelled()) {
            return PreparedTurn.cancelled(run);
        }

        ToolRoutingDecision routingDecision = prepResult.routingDecision();
        context.put(ToolRoutingDecision.class, routingDecision);
        emitRoutingNotice(routingDecision, streamSession);
        runtimeAdapter.synchronizeToolRoutingState(userId, request.sessionId(), routingDecision);
        if (streamSession.isCancelled()) {
            return PreparedTurn.cancelled(run);
        }

        return PreparedTurn.ready(run, input);
    }

    private record ParallelPrepResult(ContextEnvelope contextEnvelope, ToolRoutingDecision routingDecision) {}

    private ParallelPrepResult runParallelPreparation(
            String userId,
            String displayContent,
            MemorySourceRegistry.Channel recallChannel,
            Set<String> availableGroups,
            AgentStreamSession streamSession
    ) {
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            CompletableFuture<ContextEnvelope> contextFuture = CompletableFuture.supplyAsync(
                    () -> contextAssembler.assemble(new ContextRequest(
                            userId, displayContent, recallChannel, streamSession::isCancelled)),
                    executor);
            CompletableFuture<ToolRoutingDecision> routingFuture = CompletableFuture.supplyAsync(
                    () -> toolCapabilityRouter.route(new ToolRoutingRequest(displayContent, availableGroups)),
                    executor);
            return new ParallelPrepResult(awaitFuture(contextFuture), awaitFuture(routingFuture));
        }
    }

    private <T> T awaitFuture(CompletableFuture<T> future) {
        try {
            return future.get();
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("准备阶段被中断", exception);
        } catch (ExecutionException exception) {
            Throwable cause = exception.getCause();
            if (cause instanceof RuntimeException runtimeException) throw runtimeException;
            if (cause instanceof Error error) throw error;
            throw new IllegalStateException("准备阶段执行失败", cause);
        }
    }

    private String resolveTurnId(AgentUserCall request) {
        String resolvedTurnId = request.turnId();
        if (resolvedTurnId != null) {
            transcriptService.validateUnusedTurnId(request.sessionId(), resolvedTurnId);
            return resolvedTurnId;
        }
        return UUID.randomUUID().toString();
    }

    private List<String> persistUserImages(
            AgentUserCall request,
            String userId,
            butvan.agent.agents.session.dto.SessionSummaryDto currentSession,
            String resolvedTurnId
    ) {
        if (request.images().isEmpty()) return List.of();
        String channel = request.memoryChannel() != null
                ? request.memoryChannel().name()
                : sessionCatalogService.getChannel(request.sessionId()).name();
        return materialRecorderSupplier.get().recordUserImages(
                new ChatMaterialRecorder.SaveImagesCommand(
                        userId,
                        channel,
                        currentSession.kind().name(),
                        request.sessionId(),
                        currentSession.projectId(),
                        currentSession.title(),
                        resolvedTurnId,
                        request.images()
                ));
    }

    private void notifyUserTurnHooks(AgentUserCall request, String userId, String turnId) {
        UserTurnActivityListener listener = activityListenerSupplier.get();
        if (listener != null) {
            try {
                listener.onUserTurnRecorded(userId, request.sessionId(), request.memoryChannel());
            } catch (RuntimeException exception) {
                log.debug("用户发言监听降级：errorType={}", exception.getClass().getSimpleName());
            }
        }
        try {
            memoryLifecycleSupplier.get().admitted(request, userId, turnId);
        } catch (RuntimeException exception) {
            log.warn("经历来源登记未完成，聊天继续：errorType={}", exception.getClass().getSimpleName());
        }
    }

    private void configureReplyImages(
            RuntimeContext context,
            String sessionId,
            String userId,
            String turnId,
            butvan.agent.agents.session.dto.SessionSummaryDto currentSession,
            boolean feishuSession
    ) {
        if (feishuSession) {
            ReplyImages.disableForChannel(context);
        } else {
            context.put(ReplyImages.class, new ReplyImages(
                    new ChatMaterialRecorder.SaveImagesCommand(
                            userId, "DESKTOP", currentSession.kind().name(), sessionId,
                            currentSession.projectId(), currentSession.title(), turnId, List.of())));
        }
    }

    private Set<String> availableToolGroups(boolean feishuSession) {
        if (!feishuSession) return toolCapabilityCatalog.groupNames();
        return toolCapabilityCatalog.groupNames().stream()
                .filter(group -> !"screen".equals(group))
                .collect(Collectors.toUnmodifiableSet());
    }

    /** Jev 降级时发送非终态提示，使聊天继续执行且桌面端可以告知用户。 */
    private void emitRoutingNotice(ToolRoutingDecision decision, AgentStreamSession streamSession) {
        if (decision == null
                || decision.status() != ToolRoutingDecision.Status.FALLBACK
                || decision.failure() == null) {
            return;
        }
        var failure = decision.failure();
        streamExecutor.putEvent(streamSession, new AgentStreamEvent.RoutingNotice(
                failure.code().payloadValue(),
                failure.message(),
                failure.requestId(),
                failure.retryable(),
                failure.retryAfterMillis()
        ));
    }

    /** 校验用户输入，避免空消息和异常大的请求进入模型。 */
    String requireContent(String content) {
        if (content == null || content.isBlank()) {
            throw new IllegalArgumentException("消息内容不能为空");
        }
        String normalized = content.strip();
        if (normalized.length() > 20_000) {
            throw new IllegalArgumentException("消息内容不能超过 20000 个字符");
        }
        return normalized;
    }
}

